import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{dr as i,fr as a,mr as o,pr as s}from"./chunks/assets.juLBFQPb.js";var c=JSON.parse(`{"title":"Image pricing","description":"","frontmatter":{},"headers":[],"relativePath":"product-config/image-pricing.md","filePath":"product-config/image-pricing.md"}`),l={name:`product-config/image-pricing.md`},u=o+` 1x, `+s+` 2x`,d=a+` 1x, `+i+` 2x`;function f(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="image-pricing" tabindex="-1">Image pricing <a class="header-anchor" href="#image-pricing" aria-label="Permalink to “Image pricing”">​</a></h1><p>In this tab, you can configure the various aspects of image pricing.</p><p><img src="/webp/image-pricing.jpg-90-1788222796762.webp" srcset="`+u+`" alt="Image pricing" title="" width="1536" height="1280" loading="lazy" style="width:768px;"></p><h2 id="use-image-cost-directly" tabindex="-1">Use image cost directly <a class="header-anchor" href="#use-image-cost-directly" aria-label="Permalink to “Use image cost directly”">​</a></h2><p>This will allow using the image price without multiplying it by the area of the image.</p><p>If the image is a customer upload, then the <a href="#upload-cost">upload cost</a> will be used.</p><h2 id="image-cost" tabindex="-1">Image cost <a class="header-anchor" href="#image-cost" aria-label="Permalink to “Image cost”">​</a></h2><p>This will be added to the total for every image that is added to the design.</p><h2 id="image-cost-per-m2" tabindex="-1">Image cost per m² <a class="header-anchor" href="#image-cost-per-m2" aria-label="Permalink to “Image cost per m²”">​</a></h2><p>Configure this price if you want to replace the image prices</p><h2 id="image-cost-intervals" tabindex="-1">Image cost intervals <a class="header-anchor" href="#image-cost-intervals" aria-label="Permalink to “Image cost intervals”">​</a></h2><p>Allows setting different costs for different size ranges</p><p><img src="/webp/image-interval-cost.jpg-90-1788222796761.webp" srcset="`+d+`" alt="Image interval cost" title="" width="1448" height="802" loading="lazy" style="width:724px;"></p><h2 id="use-interval-cost-directly" tabindex="-1">Use interval cost directly <a class="header-anchor" href="#use-interval-cost-directly" aria-label="Permalink to “Use interval cost directly”">​</a></h2><p>This will add the interval cost directly without multiplying it by the area</p><h2 id="upload-cost" tabindex="-1">Upload cost <a class="header-anchor" href="#upload-cost" aria-label="Permalink to “Upload cost”">​</a></h2><p>This will be added if the image is a customer upload and if the <a href="/product-config/image-pricing.html#use-image-cost-directly">Use image cost directly</a> option is enabled</p><h2 id="upload-cost-per-m2" tabindex="-1">Upload cost per m² <a class="header-anchor" href="#upload-cost-per-m2" aria-label="Permalink to “Upload cost per m²”">​</a></h2><p>This will be added for customer uploads if the <a href="/product-config/image-pricing.html#use-image-cost-directly">Use image cost directly</a> option is not active.</p><h2 id="minimum-image-cost" tabindex="-1">Minimum image cost <a class="header-anchor" href="#minimum-image-cost" aria-label="Permalink to “Minimum image cost”">​</a></h2><p>If an image has a cost that is less than this cost then it will be assigned this minimal cost.</p><h2 id="images-total-cost" tabindex="-1">Images total cost <a class="header-anchor" href="#images-total-cost" aria-label="Permalink to “Images total cost”">​</a></h2><p>This an extra cost that will be added if the design contain at lease one image.</p>`,23)]])}var p=e(l,[[`render`,f]]);export{c as __pageData,p as default};